// The choreography being extracted: debounced input + async fetch + cancel stale requests
function useDebouncedValue(value, delayMs) {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(id);           // always clean up
  }, [value, delayMs]);

  return debounced;
}

function useSearch(query, searchFn) {
  const debouncedQuery = useDebouncedValue(query, 250);
  const [state, setState] = useState({ data: [], status: 'idle', error: null });

  useEffect(() => {
    if (!debouncedQuery) {
      setState({ data: [], status: 'idle', error: null });
      return;
    }
    const controller = new AbortController();   // stale responses must not win
    setState((s) => ({ ...s, status: 'loading' }));

    searchFn(debouncedQuery, controller.signal)
      .then((data) => setState({ data, status: 'success', error: null }))
      .catch((error) => {
        if (error.name !== 'AbortError') {
          setState({ data: [], status: 'error', error });
        }
      });

    return () => controller.abort();
  }, [debouncedQuery, searchFn]);

  return state;
}

// Consumers get behavior, not UI — each has its own independent state:
function ProductSearch() {
  const [q, setQ] = useState('');
  const { data, status } = useSearch(q, searchProducts);
  return <SearchResults items={data} loading={status === 'loading'} />;
}

function CommandPalette() {
  const [q, setQ] = useState('');
  const { data } = useSearch(q, searchCommands);   // separate state, same logic
  return <CommandList items={data} />;
}

